## Why This Is Asked

This question evaluates the ability to design an offline-first Android architecture using modern components like Jetpack Compose, Room, and WorkManager. It tests understanding of manifest-driven data flows and background synchronization suitable for beginners.

## Key Concepts

- MVVM architecture with Repository pattern
- Room database for local caching
- WorkManager for background synchronization
- Network constraints and offline-first design
- Jetpack Compose for UI rendering

## Code Example

```kotlin
data class Article(
    val id: String,
    val section: String,
    val title: String,
    val body: String,
    val updatedAt: Long
)

data class SectionManifest(
    val section: String,
    val endpoint: String
)

@Dao
interface ArticleDao {
    @Insert(onConflict = OnConflictStrategy.REPLACE)
    suspend fun insertOrUpdate(article: Article)

    @Query("SELECT * FROM articles WHERE section = :section")
    fun getBySection(section: String): Flow<List<Article>>

    @Query("DELETE FROM articles WHERE section = :section")
    suspend fun clearSection(section: String)
}

class SyncWorker(
    context: Context,
    params: WorkerParameters
) : CoroutineWorker(context, params) {

    override suspend fun doWork(): Result {
        return try {
            // Fetch manifest and sync articles
            Result.success()
        } catch (e: Exception) {
            Result.retry()
        }
    }
}

val constraints = Constraints.Builder()
    .setRequiredNetworkType(NetworkType.UNMETERED)
    .setRequiresBatteryNotLow(true)
    .build()

val syncRequest = OneTimeWorkRequestBuilder<SyncWorker>()
    .setConstraints(constraints)
    .setBackoffCriteria(
        BackoffPolicy.EXPONENTIAL,
        30,
        TimeUnit.SECONDS
    )
    .build()
```

